'use strict';
const patientStandalone=document.body?.dataset?.patientPage==='true';
let patientStep=0, patientTarget='DÉMO-001';
if(patientStandalone)view='portal';
const patientDrafts={};
const diseaseGroups={
 'Cœur et circulation':['Insuffisance cardiaque','Infarctus ou stent','Trouble du rythme','Hypertension artérielle','Phlébite ou embolie pulmonaire','Artérite'],
 'Respiration':['Asthme','Bronchite chronique','Apnée du sommeil'],
 'Digestion et appareil urinaire':['Reflux ou hernie hiatale','Ulcère gastrique','Adénome de prostate'],
 'Neurologie':['AVC','Épilepsie','Troubles psychiques'],
 'Autres maladies':['Diabète','Anomalie de la thyroïde','Insuffisance rénale','Myopathie','Myasthénie','Porphyrie']
};
const bleedingQuestions=['Maladie hémorragique dans la famille proche','Saignement du nez ou des gencives ayant nécessité une consultation','Hématomes de plus de 2 cm sans choc ou importants après un choc mineur','Saignement prolongé après extraction dentaire','Saignement important après une chirurgie mineure','Saignement gynécologique inhabituel ayant nécessité une consultation','Hémorragie lors d’un accouchement'];
const steps=['Votre intervention','Anesthésies et allergies','Votre santé','Traitements et habitudes','Vérification'];
const patientLabels={birthname:'Nom de naissance fictif',firstname:'Prénom fictif',usename:'Nom d’usage fictif',dob:'Date de naissance fictive',weight:'Poids (kg)',height:'Taille (cm)',operation:'Intervention',date:'Date prévue',allergy:'Allergies',allergyDetails:'Produit et réaction',operations:'Opérations et dates',anesthesia:'Problème lié à une anesthésie (vous ou votre famille)',anesthesiaDetails:'Précisions sur l’anesthésie',nausea:'Nausées ou vomissements après anesthésie',travel:'Mal des transports',hospital:'Hospitalisation hors chirurgie',hospitalDetails:'Motif des hospitalisations',diseases:'Maladies déclarées',other:'Autres problèmes de santé',teeth:'Dents mobiles ou refaites',stairs:'Étages montés sans arrêt',devices:'Prothèses et dispositifs',bleeding:'Antécédents de saignement',treatments:'Traitements : nom, dosage, horaires',tobacco:'Tabac',cigarettes:'Cigarettes par jour',years:'Années de tabagisme',alcohol:'Verres d’alcool par jour',drugs:'Drogues',drugDetails:'Précisions',questions:'Questions pour l’anesthésiste'};
function pf(key,label,type='text'){const d=patientDrafts[patientTarget]||{};return `<label>${label}<input name="${key}" type="${type}" value="${esc(d[key]||'')}" ${type==='number'?'min="0" step="any"':''}></label>`}
function pt(key,label){return `<label class="wide">${label}<textarea name="${key}">${esc((patientDrafts[patientTarget]||{})[key]||'')}</textarea></label>`}
function ps(key,label,options=['Oui','Non','Je ne sais pas']){return `<label>${label}<select name="${key}"><option value="">Sélectionner</option>${options.map(v=>`<option ${((patientDrafts[patientTarget]||{})[key]===v)?'selected':''}>${v}</option>`).join('')}</select></label>`}
function checks(key,items){const d=patientDrafts[patientTarget]||{};return items.map(v=>`<label class="check"><input name="${key}" type="checkbox" value="${esc(v)}" ${(d[key]||[]).includes(v)?'checked':''}>${esc(v)}</label>`).join('')}
function savePatientDraft(form){const f=new FormData(form),d=patientDrafts[patientTarget]||{};for(const [k,v] of f)d[k]=v;for(const k of ['diseases','devices','bleeding'])if(form.querySelector(`[name="${k}"]`))d[k]=f.getAll(k);patientDrafts[patientTarget]=d;}
function rawSummary(d){return Object.entries(patientLabels).filter(([k])=>d[k]&&(!Array.isArray(d[k])||d[k].length)).map(([k,label])=>`<div class="answer"><dt>${label}</dt><dd>${esc(Array.isArray(d[k])?d[k].join(', '):d[k])}</dd></div>`).join('')}
function renderPortal(){
 $('#new').hidden=true;$('#stats').hidden=true;
 const d=patientDrafts[patientTarget]||{},submitted=patients.find(x=>x.id===patientTarget)?.questionnaire;
 let body='';
 if(patientStep===0)body=pf('birthname','Nom de naissance fictif')+pf('firstname','Prénom fictif')+pf('usename','Nom d’usage fictif')+pf('dob','Date de naissance fictive','date')+pf('weight','Poids (kg)','number')+pf('height','Taille (cm)','number')+pf('operation','Intervention prévue')+pf('date','Date prévue','date');
 if(patientStep===1)body=ps('allergy','Avez-vous des allergies ?')+pt('allergyDetails','Si oui : médicament, antibiotique ou aliment et réaction observée')+pt('operations','De quoi avez-vous déjà été opéré ? Indiquez les dates.')+ps('anesthesia','Vous ou votre famille avez-vous rencontré un problème lié à l’anesthésie ?')+pt('anesthesiaDetails','Lequel ?')+ps('nausea','Nausées ou vomissements après une anesthésie ?')+ps('travel','Mal des transports ?')+ps('hospital','Hospitalisé en dehors des opérations ?')+pt('hospitalDetails','Pour quelle raison ?');
 if(patientStep===2)body=`<div class="wide"><p>Cochez les maladies qui vous concernent. Si vous avez un doute, précisez-le ci-dessous.</p>${Object.entries(diseaseGroups).map(([label,items])=>`<fieldset class="qgroup"><legend>${label}</legend>${checks('diseases',items)}</fieldset>`).join('')}</div>`+pt('other','Autres maladies ou points dont vous n’êtes pas sûr')+ps('teeth','Dents refaites, déchaussées ou qui bougent ?')+ps('stairs','Combien d’étages pouvez-vous monter sans vous arrêter ?',['Aucun','1 étage','2 étages','3 étages ou plus','Je ne sais pas'])+`<fieldset class="qgroup wide"><legend>Prothèses et dispositifs</legend>${checks('devices',['Prothèse dentaire','Prothèse auditive','Pacemaker ou défibrillateur','Ventilation nocturne'])}</fieldset><fieldset class="qgroup wide"><legend>Avez-vous déjà présenté ces problèmes de saignement ?</legend>${checks('bleeding',bleedingQuestions)}<p class="muted">Signalez les situations qui vous concernent ; elles seront revues en consultation.</p></fieldset>`;
 if(patientStep===3)body=pt('treatments','Tous vos traitements : nom, dosage, prise le matin / midi / soir. Incluez injections, automédication et compléments.')+ps('tobacco','Consommez-vous du tabac ?')+pf('cigarettes','Cigarettes par jour','number')+pf('years','Depuis combien d’années ?','number')+pf('alcohol','Verres d’alcool par jour','number')+ps('drugs','Consommez-vous des drogues ?')+pt('drugDetails','Précisions éventuelles')+pt('questions','Vos questions pour l’anesthésiste')+`<div class="notice wide">À apporter en consultation : ordonnances, courriers des spécialistes, bilans et carte de groupe sanguin si vous en avez une. Ne modifiez pas vos traitements sur la base de ce formulaire.</div>`;
 if(patientStep===4)body=`<div class="wide"><h3>Relisez vos réponses</h3><dl class="answers">${rawSummary(d)||'<p>Aucune réponse renseignée.</p>'}</dl><p class="muted">Une question sans réponse restera « non renseignée ». Elle ne sera pas interprétée comme une absence de problème.</p><label class="check"><input name="confirmed" type="checkbox" required>Je confirme les réponses de ce scénario fictif.</label></div>`;
 $('#workspace').innerHTML=`<section class="panel portal"><div class="panelhead"><span class="pill">ESPACE PATIENT · DÉMONSTRATION</span><h2 style="margin-top:16px">Préparer ma consultation</h2><p>Questionnaire adapté de votre formulaire médical. Répondez au mieux ; les réponses seront revues avec l’anesthésiste.</p><div class="notice warn">Essai avec des données fictives uniquement. Ce formulaire ne reçoit pas de données de vrais patients. Les réponses et brouillons disparaissent au rechargement.</div><label>Tester le questionnaire pour le séjour<select id="patienttarget">${patients.map(x=>`<option value="${x.id}" ${x.id===patientTarget?'selected':''}>${x.id} · ${x.specialty}</option>`).join('')}</select></label>${submitted?`<div class="notice">Questionnaire déjà reçu dans cette session : ${submitted.reviewed?'repris dans le brouillon de consultation':'à vérifier par l’anesthésiste'}. Une nouvelle soumission rouvrira la vérification.</div>`:''}<ol class="qsteps">${steps.map((s,i)=>`<li class="${i===patientStep?'current':''}" ${i===patientStep?'aria-current="step"':''}>${i+1}. ${s}</li>`).join('')}</ol></div><div class="content"><h3>Étape ${patientStep+1} / 5 · ${steps[patientStep]}</h3><form id="patientform"><div class="formgrid">${body}</div><div class="actions">${patientStep?'<button type="button" class="secondary" id="previous">Précédent</button>':''}<button type="button" class="secondary" id="draft">Garder le brouillon de session</button><button class="primary">${patientStep===4?'Simuler l’envoi à la clinique':'Suivant'}</button></div></form></div></section>`;
 $('#patienttarget').onchange=e=>{savePatientDraft($('#patientform'));patientTarget=e.target.value;patientStep=0;renderPortal()};
 $('#draft').onclick=()=>{savePatientDraft($('#patientform'));toast('Brouillon gardé pour cette session uniquement')};
 if($('#previous'))$('#previous').onclick=()=>{savePatientDraft($('#patientform'));patientStep--;renderPortal()};
 $('#patientform').onsubmit=e=>{e.preventDefault();savePatientDraft(e.currentTarget);if(patientStep<4){patientStep++;renderPortal();return}const x=patients.find(x=>x.id===patientTarget);x.questionnaire={answers:structuredClone(patientDrafts[patientTarget]),received:new Date().toLocaleString('fr-FR'),reviewed:false};x.task='Questionnaire patient à vérifier';x.done=false;x.events.unshift({at:x.questionnaire.received,role:'Patient fictif',kind:'Questionnaire',text:'Réponses patient reçues (simulation)'});if(patientStandalone){$('#workspace').innerHTML='<section class="panel portal"><div class="content"><span class="pill good">Envoi simulé terminé</span><h2 style="margin-top:18px">Votre questionnaire est complété</h2><p>Les réponses sont disponibles dans le dossier fictif de cette session. Aucune donnée n’a été envoyée à une clinique.</p><p class="muted">Le questionnaire ne remplace pas la consultation avec l’anesthésiste.</p><button class="secondary" id="restartpatient">Relire mes réponses</button></div></section>';$('#restartpatient').onclick=()=>{patientStep=4;renderPortal()};return}selected=x.id;tab='questionnaire';view='patients';render();toast('Questionnaire transféré au séjour fictif dans cette session')};
}
function questionnaireReview(){const x=p(),q=x.questionnaire;if(!q){$('#content').innerHTML='<h3>Questionnaire patient</h3><p>Aucun questionnaire reçu pour ce séjour.</p><button class="primary" id="tryquestionnaire">Tester le formulaire patient</button>';$('#tryquestionnaire').onclick=()=>{patientTarget=x.id;patientStep=0;view='portal';render()};return}
 const d=q.answers,attention=[];if(d.allergy==='Oui')attention.push('Allergie déclarée : vérifier le produit et la réaction');if(d.anesthesia==='Oui')attention.push('Problème anesthésique personnel ou familial à préciser');if(d.bleeding?.length)attention.push('Antécédents de saignement à explorer');if(d.devices?.some(v=>v.includes('Pacemaker')))attention.push('Pacemaker ou défibrillateur à documenter');if(d.diseases?.includes('Apnée du sommeil'))attention.push('Apnée du sommeil déclarée');if(d.treatments)attention.push('Traitements à rapprocher de l’ordonnance');
 $('#content').innerHTML=`<h3>Réponses du patient · ${q.reviewed?'Reprises dans le brouillon':'À vérifier'}</h3><p class="muted">Reçues le ${esc(q.received)} · déclarations du patient fictif, à confirmer en consultation.</p>${attention.length?`<div class="notice warn"><strong>Points à vérifier</strong><ul>${attention.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div>`:''}<dl class="answers">${rawSummary(d)}</dl><div class="notice">Les réponses restent distinctes de l’évaluation médicale. Aucun score ni traitement n’est déduit automatiquement.</div><button class="primary" id="importanswers" ${role!=='Anesthésiste'||q.reviewed?'disabled':''}>${q.reviewed?'Réponses reprises':'Confirmer la revue et reprendre dans le brouillon'}</button><p class="muted">Action réservée au profil anesthésiste simulé. Une consultation déjà validée doit être rouverte.</p>`;
 $('#importanswers').onclick=()=>{if(role!=='Anesthésiste'||q.reviewed)return;if(x.consult.validated){toast('Ouvrez une révision de la consultation avant de reprendre les réponses.');return}const c=x.consult,append=(old,s)=>[old,s].filter(Boolean).join('\n');c.history=append(c.history,['Questionnaire patient revu :',d.diseases?.join(', '),d.operations&&'Opérations : '+d.operations,d.hospitalDetails&&'Hospitalisations : '+d.hospitalDetails,d.other,d.anesthesiaDetails&&'Anesthésie : '+d.anesthesiaDetails,d.bleeding?.length&&'Saignements : '+d.bleeding.join('; ')].filter(Boolean).join('\n'));if(d.allergy)c.allergies=append(c.allergies,'Déclaration revue : '+d.allergy+(d.allergyDetails?' — '+d.allergyDetails:''));if(d.treatments)c.treatments=append(c.treatments,d.treatments);q.reviewed=true;q.reviewedAt=new Date().toLocaleString('fr-FR');x.task='Consultation à compléter';event('Questionnaire revu et repris dans le brouillon (simulation)','Questionnaire');detail();toast('Réponses reprises ; consultation médicale à compléter et valider')};
}
const baseRender=render;render=function(){ $('#new').hidden=view==='portal';$('#stats').hidden=view==='portal';baseRender()};
